<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Dashboard extends Controller {
 public function index():void{$this->handleCors();$this->admin();$q=fn($sql)=>(int)($this->db()->query($sql)->row_array()['c']??0);$ordersTotal=$q('SELECT COUNT(*) c FROM vp_orders');$processing=$q("SELECT COUNT(*) c FROM vp_orders WHERE status IN('processing','paid')");$pending=$q("SELECT COUNT(*) c FROM vp_orders WHERE status='pending_payment'");$shipped=$q("SELECT COUNT(*) c FROM vp_orders WHERE status='shipped'");$completed=$q("SELECT COUNT(*) c FROM vp_orders WHERE status='completed'");$products=$q("SELECT COUNT(*) c FROM vp_products WHERE status='published'");$customers=$q('SELECT COUNT(*) c FROM vp_customers');$revenue=(float)($this->db()->query("SELECT COALESCE(SUM(o.total),0) s FROM vp_orders o WHERE o.status IN('paid','processing','shipped','completed')")->row_array()['s']??0);$recent=$this->db()->query('SELECT o.id,o.order_number,o.status,o.total,o.created_at,c.full_name customer_name FROM vp_orders o INNER JOIN vp_customers c ON c.id=o.customer_id ORDER BY o.created_at DESC LIMIT 8')->result_array()?:[];foreach($recent as &$r){$r['id']=(int)$r['id'];$r['total']=(float)$r['total'];}unset($r);$newCustomers=$this->db()->query('SELECT id,full_name,email,created_at FROM vp_customers ORDER BY created_at DESC LIMIT 5')->result_array()?:[];foreach($newCustomers as &$c){$c['id']=(int)$c['id'];}unset($c);$this->success(['ordersTotal'=>$ordersTotal,'processing'=>$processing,'pending'=>$pending,'shipped'=>$shipped,'completed'=>$completed,'products'=>$products,'customers'=>$customers,'revenue'=>$revenue,'recentOrders'=>$recent,'newCustomers'=>$newCustomers],'Dashboard loaded');}
 private function admin():array{$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);return $a;}
}
